const totalReportes = $('Total reportes').item.json.total;
const reportes24h = $('Reportes 24h').item.json.total;
const reportesPorTipo = $('Reportes por tipo').all().map(i => ({ name: i.json.name, value: i.json.value }));
const reportesPorSeveridad = $('Reportes por severidad').all().map(i => ({ name: i.json.name, value: i.json.value }));
const tendencia = $('Tendencia 30 dias').all().map(i => ({ name: i.json.name, value: i.json.value }));
const congestion = $('Congestion snapshot').item.json;
const siniestrosPorDistrito = $('Siniestros por distrito').all().map(i => ({ name: i.json.name, value: i.json.value }));
const siniestrosPorClase = $('Siniestros por clase').all().map(i => ({ name: i.json.name, value: i.json.value, fallecidos: i.json.fallecidos }));
const siniestrosTotales = $('Siniestros totales').item.json;
const siniestrosSutranTotales = $('Siniestros SUTRAN totales').item.json;
const siniestrosSutranPorDepartamento = $('Siniestros SUTRAN por departamento').all().map(i => ({ name: i.json.name, value: i.json.value }));
const siniestrosSutranPorModalidad = $('Siniestros SUTRAN por modalidad').all().map(i => ({ name: i.json.name, value: i.json.value, fallecidos: i.json.fallecidos }));

return [{
  json: {
    kpis: {
      total_reportes: totalReportes,
      reportes_ultimas_24h: reportes24h,
      congestion_promedio: congestion.congestion_promedio != null ? Number(congestion.congestion_promedio) : null,
      puntos_congestionados: congestion.puntos_congestionados,
      total_puntos_monitoreo: congestion.total_puntos,
      total_siniestros_fatales: siniestrosTotales.total,
      total_fallecidos_historico: siniestrosTotales.fallecidos_total,
      total_siniestros_sutran: siniestrosSutranTotales.total,
      total_fallecidos_sutran: siniestrosSutranTotales.fallecidos_total,
      total_heridos_sutran: siniestrosSutranTotales.heridos_total
    },
    charts: {
      reportes_por_tipo: reportesPorTipo,
      reportes_por_severidad: reportesPorSeveridad,
      tendencia_reportes_30d: tendencia,
      siniestros_por_distrito: siniestrosPorDistrito,
      siniestros_por_clase: siniestrosPorClase,
      siniestros_sutran_por_departamento: siniestrosSutranPorDepartamento,
      siniestros_sutran_por_modalidad: siniestrosSutranPorModalidad
    },
    generated_at: new Date().toISOString()
  }
}];

// HT-51 T03: sobre del contrato 4.7 para reporte.estado_cambiado
const r = $('Marcar reporte').first().json;
const distrito = $('Distrito del reporte resuelto').first().json.distrito || 'Sin distrito';

const hora = new Date(new Date(r.created_at || Date.now()).getTime() - 5 * 3600 * 1000).getUTCHours();
const franja = hora >= 6 && hora < 12 ? 'manana' : hora >= 12 && hora < 18 ? 'tarde' : 'noche';

return [{
  json: {
    id: $('Generar ID estado_cambiado').first().json.eventoId,
    tipo: 'reporte.estado_cambiado',
    fecha: new Date().toISOString(),
    origen: 'n8n/report-resolve',
    datos: {
      reporte_id: r.id,
      distrito,
      franja,
      tipo_incidente: r.incident_type,
      estado_anterior: r.estado_anterior,
      estado_nuevo: r.status,
    },
  },
}];

// Respuesta IDENTICA a la de antes para mf-gestion-incidentes:
// { id, status, resolved_at } si se actualizo, o un objeto vacio si no.
const filas = $('Marcar reporte').all().filter((i) => i.json && i.json.id);
if (!filas.length) return [{ json: {} }];
return filas.map((i) => ({ json: { id: i.json.id, status: i.json.status, resolved_at: i.json.resolved_at } }));

// Copia EN LINEA del subworkflow «Validar token» (HT-36 T01): llamarlo con
// Execute Workflow sumaba unos 5 s por peticion en la instancia de Lightsail.
// Solo cambia de donde sale la entrada; el resto debe ser identico
// (lo comprueba ia-ops/workflows/tests/test_validar_token.py).
// HT-36 T01 - Valida el token de sesion (contrato C1).
//
// El token lo emite el login de Central (nodo "Generar token"):
//   base64url(payload) + "." + HMAC-SHA256 en hex del primer tramo, con
//   N8N_AUTH_SECRET; payload { sub, id, role, iat, exp } con exp en ms.
// Salida: { valido: true, usuario_id, rol, exp (segundos) } o
//         { valido: false, http_code: 401 | 403 | 500, error }.
// Quien llama responde el error al cliente con ese codigo.
const crypto = require('crypto');

// Transicion: mientras la app no envie el token (HT-36 T03, TE_ENVIAR_TOKEN),
// los webhooks que ya existian (reports-list, reports-history, report-resolve)
// llaman con permitir_sin_token=true: una peticion SIN cabecera sigue como
// antes y el webhook usa el usuario que manda el cuerpo. Con cabecera se
// valida siempre. Los webhooks nuevos no lo pasan y exigen el token.
// Pasar EXIGIR_TOKEN a true cuando TE_ENVIAR_TOKEN este activo en produccion.
const EXIGIR_TOKEN = false;

const NIVEL = { ciudadano: 1, operador: 2 };
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

const entrada = {
  rol_minimo: 'ciudadano',
  permitir_sin_token: true,
  authorization: ($input.first().json.headers || {}).authorization || '',
};
// Un rol_minimo desconocido exige lo maximo: nunca abre una ruta por error.
const rolMinimo = NIVEL[entrada.rol_minimo] ? entrada.rol_minimo : 'operador';
const cabecera = String(entrada.authorization || '').trim();
const rechazar = (http_code, error) => [{ json: { valido: false, http_code, error } }];

const permitirSinToken = entrada.permitir_sin_token === true || entrada.permitir_sin_token === 'true';

if (!cabecera) {
  if (EXIGIR_TOKEN || !permitirSinToken) return rechazar(401, 'token_invalido');
  return [{ json: { valido: true, sin_token: true, usuario_id: null, rol: null, exp: null } }];
}

const partes = cabecera.match(/^Bearer\s+([A-Za-z0-9_-]+)\.([0-9a-f]{64})$/i);
if (!partes) return rechazar(401, 'token_invalido');

let secreto = null;
try {
  secreto = $env.N8N_AUTH_SECRET || null;
} catch (e) {
  secreto = null;
}
if (!secreto) return rechazar(500, 'autenticacion_no_configurada');

// Comparacion en tiempo constante, sobre bytes del mismo largo.
const esperada = Buffer.from(crypto.createHmac('sha256', secreto).update(partes[1]).digest('hex'), 'hex');
const recibida = Buffer.from(partes[2].toLowerCase(), 'hex');
if (esperada.length !== recibida.length || !crypto.timingSafeEqual(esperada, recibida)) {
  return rechazar(401, 'token_invalido');
}

let payload;
try {
  payload = JSON.parse(Buffer.from(partes[1], 'base64url').toString('utf8'));
} catch (e) {
  return rechazar(401, 'token_invalido');
}

const expMs = Number(payload.exp);
if (!Number.isFinite(expMs) || expMs <= Date.now()) return rechazar(401, 'token_invalido');
if (!UUID.test(String(payload.id || ''))) return rechazar(401, 'token_invalido');
if (!NIVEL[payload.role]) return rechazar(401, 'token_invalido');
if (NIVEL[payload.role] < NIVEL[rolMinimo]) return rechazar(403, 'rol_no_permitido');

return [{
  json: {
    valido: true,
    sin_token: false,
    usuario_id: payload.id,
    rol: payload.role,
    exp: Math.floor(expMs / 1000),
  },
}];

